        # DD/MM/YYYY
        m = re.match(r'^(\d{1,2})/(\d{1,2})/(\d{4})$', s)
        if m:
            d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
            try:
                return datetime(y, mo, d).strftime('%Y-%m-%d')
            except ValueError:
                return None
        # YYYY-MM-DD
        m = re.match(r'^(\d{4})-(\d{1,2})-(\d{1,2})$', s)
        if m:
            y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
            try:
                return datetime(y, mo, d).strftime('%Y-%m-%d')
            except ValueError:
                return None
        # D Mon YYYY
        m = re.match(r'^(\d{1,2})\s+([A-Za-z]{3})\s+(\d{4})$', s)
        if m:
            d = int(m.group(1))
            mon = m.group(2).lower()
            y = int(m.group(3))
            if mon in month_map:
                mo = month_map[mon]
                try:
                    return datetime(y, mo, d).strftime('%Y-%m-%d')
                except ValueError:
                    return None
        return None

    def parse_amount(s):
