            negative = True
            s = s[1:-1].strip()
        # Check for DR suffix
        elif s.upper().endswith(' DR'):
            negative = True
            s = s[:-3].strip()
        # Remove currency symbols
        s = s.lstrip('₹$').strip()
        # Remove thousands commas
        s = s.replace(',', '')
        try:
            val = float(s)
            return -val if negative else val
        except ValueError:
            return None

