    for s, e in cancels:
        events.append((s, 2, None))
        events.append((e, 3, None))

    events.sort(key=lambda ev: (ev[0], 0 if ev[1] in (1, 3) else 1, ev[1]))

    active_prios = []
    prio_count = defaultdict(int)
    active_cancels = 0
    active_count = 0
    result = []
    prev_time = None

    for t, typ, val in events:
        if prev_time is not None and t > prev_time:
            if active_cancels == 0 and active_count > 0:
                while active_prios and prio_count[-active_prios[0]] == 0:
                    heapq.heappop(active_prios)
                mx = -active_prios[0]
                if result and result[-1][1] == prev_time and result[-1][2] == mx:
                    result[-1] = (result[-1][0], t, mx)
                else:
                    result.append((prev_time, t, mx))
        if typ == 0:
            active_count += 1
            prio_count[val] += 1
            heapq.heappush(active_prios, -val)
        elif typ == 1:
            active_count -= 1
            prio_count[val] -= 1
        elif typ == 2:
