    events = []
    for s, e, p in intervals:
        events.append((s, 1, p))
        events.append((e, 0, p))
    events.sort()
    active = []
    segments = []
    prev_t = None
    for t, typ, p in events:
        if prev_t is not None and t > prev_t and active:
            maxp = active[-1]
            if segments and segments[-1][1] == prev_t and segments[-1][2] == maxp:
                segments[-1] = (segments[-1][0], t, maxp)
            else:
                segments.append((prev_t, t, maxp))
        if typ == 0:
            idx = bisect_left(active, p)
            del active[idx]
        else:
            insort(active, p)
        prev_t = t
    if not cancels:
        return segments
    cans = sorted(cancels)
    merged_cans = []
    for s, e in cans:
        if merged_cans and s <= merged_cans[-1][1]:
            merged_cans[-1] = (merged_cans[-1][0], max(merged_cans[-1][1], e))
        else:
            merged_cans.append((s, e))
    result = []
    for seg_s, seg_e, prio in segments:
