    return result

def merge_busy2(intervals, cancels):
    from collections import Counter
    import heapq
    if not intervals:
        return []
    events = []
    for s, e, p in intervals:
        events.append((s, 1, p))
        events.append((e, -1, p))
    events.sort(key=lambda x: (x[0], x[1]))
    active = Counter()
    maxheap = []
    timeline = []
    prev_t = None
    current_max = None
    for t, typ, p in events:
        if prev_t is not None and t > prev_t and current_max is not None:
            if timeline and timeline[-1][1] == prev_t and timeline[-1][2] == current_max:
                timeline[-1] = (timeline[-1][0], t, current_max)
            else:
                timeline.append((prev_t, t, current_max))
        if typ == 1:
            active[p] += 1
            heapq.heappush(maxheap, -p)
        else:
            active[p] -= 1
            if active[p] == 0:
                del active[p]
        while maxheap and active.get(-maxheap[0], 0) == 0:
            heapq.heappop(maxheap)
        current_max = -maxheap[0] if maxheap else None
        prev_t = t
    if not cancels:
        return timeline
    events_c = []
    for s, e in cancels:
        events_c.append((s, 1))
        events_c.append((e, -1))
    events_c.sort(key=lambda x: (x[0], x[1]))
    cancel_union = []
    count = 0
    prev = None
    for t, typ in events_c:
        if prev is not None and t > prev and count > 0:
            if cancel_union and cancel_union[-1][1] == prev:
                cancel_union[-1] = (cancel_union[-1][0], t)
            else:
                cancel_union.append((prev, t))
        count += typ
        prev = t
    result = []
    i = 0
    n_c = len(cancel_union)
    for s, e, p in timeline:
        cur = s
        while i < n_c and cancel_union[i][1] <= cur:
            i += 1
        j = i
        while j < n_c and cancel_union[j][0] < e:
            cs, ce = cancel_union[j]
            if cs > cur:
                free_end = min(cs, e)
                if free_end > cur:
                    if result and result[-1][1] == cur and result[-1][2] == p:
                        result[-1] = (result[-1][0], free_end, p)
                    else:
                        result.append((cur, free_end, p))
            cur = max(cur, min(ce, e))
            if cur >= e:
                break
            j += 1
        if cur < e:
            if result and result[-1][1] == cur and result[-1][2] == p:
                result[-1] = (result[-1][0], e, p)
            else:
                result.append((cur, e, p))
    return result

class RateTree:
    def __init__(self, spec):
        self.parent = {}
        self.capacity = {}
        self.rate = {}
        self.tokens = {}
        self.last = {}
        for name, (capacity, refill_rate, parent) in spec.items():
            self.parent[name] = parent
            self.capacity[name] = float(capacity)
            self.rate[name] = float(refill_rate)
            self.tokens[name] = float(capacity)
            self.last[name] = float('-inf')

    def allow(self, name, n=1.0, now=0.0):
        path = []
        cur = name
        while cur is not None:
            path.append(cur)
            cur = self.parent[cur]
        for node in path:
            self._refill(node, now)
        if any(self.tokens[node] < n for node in path):
            return False
        for node in path:
            self.tokens[node] -= n
        return True

    def _refill(self, node, now):
        last = self.last[node]
        if now > last:
            elapsed = now - last
            self.tokens[node] = min(
                self.capacity[node],
                self.tokens[node] + elapsed * self.rate[node]
            )
            self.last[node] = now

class RateTree:
    def __init__(self, spec: dict):
        self._nodes = {}
        for name, (capacity, refill_rate, parent) in spec.items():
            self._nodes[name] = {
                "capacity": float(capacity),
                "refill_rate": float(refill_rate),
                "parent": parent,
                "tokens": float(capacity),
                "last": None,
            }

    def _path(self, name: str) -> list:
        path = []
        while name is not None:
            path.append(name)
            name = self._nodes[name]["parent"]
        return path

    def allow(self, name: str, n: float = 1.0, now: float = 0.0) -> bool:
        path = self._path(name)
        for node_name in path:
            node = self._nodes[node_name]
            if node["last"] is None:
                elapsed = 0.0
            else:
                elapsed = max(0.0, now - node["last"])
            node["tokens"] = min(
                node["capacity"],
                node["tokens"] + elapsed * node["refill_rate"],
            )
            node["last"] = now
        if all(self._nodes[nm]["tokens"] >= n for nm in path):
            for nm in path:
                self._nodes[nm]["tokens"] -= n
            return True
        return False

