                'last': 0.0,
            }

    def allow(self, name: str, n: float = 1.0, now: float = 0.0) -> bool:
        path = []
        node = name
        while node is not None:
            path.append(node)
            node = self._nodes[node]['parent']

        for node in path:
            data = self._nodes[node]
            elapsed = max(0.0, now - data['last'])
            data['tokens'] = min(data['capacity'], data['tokens'] + elapsed * data['rate'])
            data['last'] = now

        if all(self._nodes[node]['tokens'] >= n for node in path):
            for node in path:
                self._nodes[node]['tokens'] -= n
            return True
        return False

class RateTree:
    def __init__(self, spec):
        self._capacity = {}
        self._rate = {}
        self._parent = {}
        self._tokens = {}
        self._last = {}
        for name, (capacity, refill_rate, parent) in spec.items():
            self._capacity[name] = float(capacity)
            self._rate[name] = float(refill_rate)
            self._parent[name] = parent
            self._tokens[name] = float(capacity)
            self._last[name] = None

    def _update(self, name, now):
        last = self._last[name]
        if last is None:
            self._last[name] = now
            return
        if now > last:
            elapsed = now - last
            self._tokens[name] = min(
                self._capacity[name],
                self._tokens[name] + elapsed * self._rate[name],
            )
            self._last[name] = now

    def allow(self, name, n=1.0, now=0.0):
        path = []
        cur = name
        while cur is not None:
            path.append(cur)
            cur = self._parent[cur]
        for node in path:
            self._update(node, now)
        if any(self._tokens[node] < n for node in path):
            return False
        for node in path:
            self._tokens[node] -= n
        return True

