def parse_ledger(text):
    MONTHS = {
        'Jan': 1, 'Feb': 2, 'Mar': 3, 'Apr': 4, 'May': 5, 'Jun': 6,
        'Jul': 7, 'Aug': 8, 'Sep': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12
    }
    RATES = {'INR': 1.0, 'USD': 83.5, 'EUR': 90.25}
    CURRENCIES = set(RATES)

    date_re = re.compile(
        r'^(?:'
        r'(\d{2}/\d{2}/\d{4})|'                                  # DD/MM/YYYY
        r'(\d{4}-\d{2}-\d{2})|'                                  # YYYY-MM-DD
        r'(\d{1,2}\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+\d{4})|'  # D Mon YYYY
        r'((?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+\d{1,2},\s*\d{4})'  # Mon D, YYYY
        r')$'
    )

    def parse_date(s):
        s = s.strip()
        m = date_re.match(s)
        if not m:
            return None
        if m.group(1):  # DD/MM/YYYY
            try:
                return datetime.strptime(m.group(1), '%d/%m/%Y').strftime('%Y-%m-%d')
            except ValueError:
                return None
        if m.group(2):  # YYYY-MM-DD
            try:
                return datetime.strptime(m.group(2), '%Y-%m-%d').strftime('%Y-%m-%d')
            except ValueError:
                return None
        if m.group(3):  # D Mon YYYY
            try:
                return datetime.strptime(m.group(3), '%d %b %Y').strftime('%Y-%m-%d')
            except ValueError:
                return None
        if m.group(4):  # Mon D, YYYY
            try:
                # normalize possible extra spaces around comma
                cleaned = re.sub(r',\s*', ', ', m.group(4).strip())
                return datetime.strptime(cleaned, '%b %d, %Y').strftime('%Y-%m-%d')
            except ValueError:
                return None
        return None

    def parse_amount(amt_str, currency):
        s = amt_str.strip()
        if not s:
            return None
        negative = False
        # DR suffix
        if re.search(r'\s+DR\s*$', s, re.IGNORECASE):
            negative = True
            s = re.sub(r'\s+DR\s*$', '', s, flags=re.IGNORECASE).strip()
        # parentheses
        if s.startswith('(') and s.endswith(')'):
            negative = True
            s = s[1:-1].strip()
        # strip currency symbols (ignore mismatch; currency column wins)
        s = re.sub(r'^[₹$€]\s*', '', s).strip()
        # remove thousands commas
        s = s.replace(',', '')
        if not s:
            return None
        try:
            val = float(s)
        except ValueError:
            return None
        if negative:
            val = -val
        rate = RATES.get(currency)
        if rate is None:
            return None
        return round(val * rate, 2)

    # Match a whole line: date , desc , amount , currency
    # desc is either "..." (with "") or unquoted with no commas
    line_re = re.compile(
        r'^\s*'
        r'(?P<date>.*?)\s*,\s*'
        r'(?P<desc>"(?:[^"]|"")*"|[^,]*)\s*,\s*'
        r'(?P<amount>.*?)\s*,\s*'
        r'(?P<currency>INR|USD|EUR)\s*$'
    )

    results = []
    seen = set()

    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue
        m = line_re.match(line)
        if not m:
            continue
        date_raw = m.group('date').strip()
        desc_raw = m.group('desc').strip()
        amt_raw = m.group('amount').strip()
        curr = m.group('currency')

        # parse date
        iso_date = parse_date(date_raw)
        if iso_date is None:
            continue

        # parse description
        if desc_raw.startswith('"') and desc_raw.endswith('"'):
            # un-escape "" -> "
            desc = desc_raw[1:-1].replace('""', '"')
        else:
            desc = desc_raw
        desc = desc.strip()
        # empty description is allowed? yes, as long as it parses

        # parse amount
        amount_inr = parse_amount(amt_raw, curr)
        if amount_inr is None:
            continue

        key = (iso_date, desc, amount_inr)
        if key in seen:
            continue
        seen.add(key)
        results.append({
            'date': iso_date,
            'description': desc,
            'amount_inr': amount_inr
        })

    # sort: date ASC, then abs(amount_inr) DESC, stable
    results.sort(key=lambda r: (r['date'], -abs(r['amount_inr'])))
    return results

