def elapsed_seconds(tz_name, start, end):
    from datetime import datetime, timedelta
    from zoneinfo import ZoneInfo, NonExistentTimeError

    tz = ZoneInfo(tz_name)

    def to_aware(s):
        naive = datetime.strptime(s, "%Y-%m-%d %H:%M:%S")
        try:
            return naive.replace(tzinfo=tz)
        except NonExistentTimeError:
            # Non-existent (spring-forward) time: interpret with the
            # offset that was in force immediately before the jump.
            earlier = (naive - timedelta(hours=1)).replace(tzinfo=tz)
            return earlier + timedelta(hours=1)

    start_dt = to_aware(start)
    end_dt = to_aware(end)
    return (end_dt - start_dt).total_seconds()

from decimal import Decimal, ROUND_HALF_EVEN

def split_bill(amounts, n):
    total = sum(Decimal(a) for a in amounts)
    rounded = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN)
    total_cents = int(rounded * 100)
    base, rem = divmod(total_cents, n)
    return [
        f"{(base + (i < rem)) // 100}.{(base + (i < rem)) % 100:02d}"
        for i in range(n)
    ]

def truncate_graphemes(s, n):
    import unicodedata
    clusters = []
    current = []
    pending_force = False
    for char in s:
        is_mn = unicodedata.category(char) == 'Mn'
        is_zwj = char == '\u200d'
        if current and not (is_mn or is_zwj or pending_force):
            clusters.append(''.join(current))
            if len(clusters) > n:
                return ''.join(clusters[:n]) + '...'
